from __future__ import annotations

import asyncio
import pathlib
from functools import cached_property
from itertools import chain
from typing import Iterable

import attr
import taf.config.testline.testline  # type: ignore[import-untyped]

from taf.ul.ue.sim.env_setup.devices.vcu import VCU
from taf.ul.ue.sim.env_setup.devices.vdu import VDU
from taf.ul.ue.sim.env_setup.utils.config_validators import parse_conf_data_to_list


@attr.s(cmp=False, hash=True)
class CloudBTS:
    idx = attr.ib(type=int)
    configuration = attr.ib(type=taf.config.testline.testline.TestLine, hash=False)
    bts_id = attr.ib(type=str)
    remote_host = attr.ib(type=str)
    _output_directory_path = attr.ib(type=pathlib.Path)
    config_type = attr.ib(type="str")
    _user_flags = attr.ib(type=dict, hash=False)
    name = attr.ib(default="", type=str, init=False)
    suite_config_dir = attr.ib(default="", type=str, init=False)
    _vcu_scfc_names = attr.ib(default=attr.Factory(list), type=list[str], init=False)
    _vdu_scfc_names = attr.ib(default=attr.Factory(list), type=list[str], init=False)
    _vcus = attr.ib(default=attr.Factory(list), type=list[VCU], init=False)
    _vdus = attr.ib(default=attr.Factory(list), type=list[VDU], init=False)

    def __attrs_post_init__(self):
        self._create_vdus()
        self._create_vcus()

    @property
    def vcu_scfc_names(self):
        return self._vcu_scfc_names

    @vcu_scfc_names.setter
    def vcu_scfc_names(self, value):
        for idx, conf in enumerate(parse_conf_data_to_list(value)):
            self._vcus[idx].scfc_name = pathlib.Path(conf)

    @property
    def vdu_scfc_names(self):
        return self._vdu_scfc_names

    @vdu_scfc_names.setter
    def vdu_scfc_names(self, value):
        for idx, conf in enumerate(parse_conf_data_to_list(value)):
            self._vdus[idx].scfc_name = pathlib.Path(conf)

    @property
    def output_directory_path(self):
        return self._output_directory_path

    @output_directory_path.setter
    def output_directory_path(self, value: str | pathlib.Path):
        if isinstance(value, str):
            value = pathlib.Path(value)
        self._output_directory_path = value
        self._update_vcu_and_vdu_output_dir_path(value)

    def _update_vcu_and_vdu_output_dir_path(self, value):
        for vcu in self._vcus:
            vcu.output_directory_path = value
        for vdu in self._vdus:
            vdu.output_directory_path = value

    @cached_property
    def targetbd(self) -> str:
        return self._vdus[0].targetbd

    def recover_ssh(self):
        raise NotImplementedError("Recover SSH not implemented for Cloud BTS. Access to vDU should always work.")

    def wait_for_rmods_up(self, timeout: float) -> None:
        asyncio.run(self._wait_for_rmods_up(timeout))

    def configure(self):
        asyncio.run(self._configure_all_components())

    def ensure_on_air_state(self, timeout: float):
        asyncio.run(self._ensure_on_air_state(timeout))

    async def _ensure_on_air_state(self, timeout: float):
        tasks_list = [component.verify_all_is_up(timeout) for component in await self._get_all_components()]
        await asyncio.gather(*tasks_list)

    async def _wait_for_rmods_up(self, timeout: float) -> None:
        tasks_list = [component.wait_for_rmods_up(timeout) for component in self._vdus]
        await asyncio.gather(*tasks_list)

    def _create_vdus(self) -> None:
        for idx, vdu in enumerate(self.configuration.dus):
            vdu = VDU(
                idx, vdu, self.bts_id, self.remote_host, self.output_directory_path, self.config_type, self._user_flags
            )
            self._vdus.append(vdu)

    def _create_vcus(self) -> None:
        vcu = VCU(
            0,
            self.configuration.cu,
            self.bts_id,
            self.remote_host,
            self.output_directory_path,
            self.config_type,
            self._user_flags,
        )
        self._vcus.append(vcu)

    async def _get_all_components(self) -> Iterable[VCU | VDU]:
        return chain(self._vcus, self._vdus)

    async def _configure_all_components(self):
        tasks_list = [component.configure() for component in await self._get_all_components()]
        await asyncio.gather(*tasks_list)
